productCollectionsByRoom.query:
query productCollectionsByRoom($room: String!, $filters: CollectionFiltersInput!, $sortBy: String!) {
  productCollectionsByRoom(room: $room, filters: $filters, sortBy: $sortBy) {
    ...ProductCollectionDetails
    __typename
  }
}

fragment ProductCollectionDetails on ProductCollection {
  id
  itemClass
  family
  room
  factories
  origins
  flow
  status
  itemClassStatus
  smallImage {
    ...ImageFileUrl
    __typename
  }
  __typename
}

fragment ImageFileUrl on AwsImageReferenceType {
  fileUrl
  __typename
}

productsByCollection.query:
query productsByCollection($room: String!, $family: String!, $itemClass: String!, $filters: CollectionFiltersInput!, $sortBy: String!, $inStock: Boolean!, $skip: Int!, $pageSize: Int!) {
  productsByCollection(
    room: $room
    family: $family
    itemClass: $itemClass
    filters: $filters
    sortBy: $sortBy
    inStock: $inStock
    skip: $skip
    pageSize: $pageSize
  ) {
    products {
      ...ProductWithPricesEsd
      __typename
    }
    family
    totalRows
    __typename
  }
  collectionFacets(
    room: $room
    family: $family
    itemClass: $itemClass
    inStock: $inStock
  ) {
    kit {
      ...FacetCount
      __typename
    }
    type {
      ...FacetCount
      __typename
    }
    color {
      ...FacetCount
      __typename
    }
    shape {
      ...FacetCount
      __typename
    }
    size {
      ...FacetCount
      __typename
    }
    maxSize {
      ...FacetCount
      __typename
    }
    pricePoint {
      ...FacetCount
      __typename
    }
    itemStyle {
      ...FacetCount
      __typename
    }
    numberOfItemsInKit {
      ...FacetCount
      __typename
    }
    status {
      ...FacetCount
      __typename
    }
    allKits {
      ...MegaMenuBasic
      __typename
    }
    allProducts {
      ...FacetCount
      __typename
    }
    __typename
  }
}

fragment ProductWithPricesEsd on ProductWithPrice {
  id
  itemClass
  family
  room
  longDescription
  name
  groupName
  theme
  status
  seasonalSpecial
  epCubes
  price
  priceData {
    price
    originalPrice
    retailerPrice
    discountPercent
    __typename
  }
  availableAsESD {
    warehouse
    qty
    dateAvailable
    futureQty
    __typename
  }
  flags {
    closeout
    __typename
  }
  inventory {
    total
    __typename
  }
  sku {
    number
    group
    __typename
  }
  images {
    ...SmallImages
    __typename
  }
  documents {
    assemblyInstructions {
      url
      modified
      __typename
    }
    __typename
  }
  __typename
}

fragment SmallImages on BasicProductImagesType {
  primary {
    small {
      ...FileUrl
      __typename
    }
    __typename
  }
  secondary {
    small {
      ...FileUrl
      __typename
    }
    __typename
  }
  __typename
}

fragment FileUrl on AwsImageReferenceType {
  fileUrl
  __typename
}

fragment FacetCount on FacetListType {
  name
  values {
    count
    range
    __typename
  }
  __typename
}

fragment MegaMenuBasic on MegaMenu {
  room
  path
  pathSlug
  imageUrl
  __typename
}
